class Emitter {
  listeners = new Map();
  on(name, fn) {
    this.listeners.set(name, [...(this.listeners.get(name) ?? []), fn]);
    return () => this.off(name, fn);
  }
  off(name, fn) {
    const list = this.listeners.get(name) ?? [];
    this.listeners.set(name, list.filter((item) => item !== fn));
  }
  emit(name, ...args) {
    for (const fn of this.listeners.get(name) ?? []) fn(...args);
  }
}

const tv = new Emitter();
const show = (channel) => console.log(`show ${channel}`);
tv.on("switch", show);
const stop = tv.on("switch", show);
tv.emit("switch", 1);
stop();
tv.emit("switch", 2);
tv.on("switch", (channel) => console.log(`log ${channel}`));
tv.emit("switch", 3);
